507	    if (io->read(&rec_type, sizeof(int32_t), io->io_ctx) < sizeof(int32_t)) {
508	        retval = READSTAT_ERROR_READ;
509	        goto cleanup;
510	    }
511	    if (ctx->bswap)
512	        rec_type = byteswap4(rec_type);
513	    
514	    if (rec_type != 4) {
515	        retval = READSTAT_ERROR_PARSE;
516	        goto cleanup;
517	    }
518	    if (io->read(&var_count, sizeof(uint32_t), io->io_ctx) < sizeof(uint32_t)) {
519	        retval = READSTAT_ERROR_READ;
520	        goto cleanup;
521	    }
522	    if (ctx->bswap)
523	        var_count = byteswap4(var_count);
524	    
525	    if (var_count && (vars = readstat_malloc(var_count * sizeof(uint32_t))) == NULL) {
526	        retval = READSTAT_ERROR_MALLOC;
527	        goto cleanup;
528	    }
529	    if (io->read(vars, var_count * sizeof(uint32_t), io->io_ctx) < var_count * sizeof(uint32_t)) {
530	        retval = READSTAT_ERROR_READ;
531	        goto cleanup;
532	    }
533	    for (i=0; i<var_count; i++) {
534	        uint32_t var_offset = vars[i];
535	        if (ctx->bswap)
536	            var_offset = byteswap4(var_offset);
537	
538	        var_offset--; // Why subtract 1????
539	        spss_varinfo_t **var = bsearch(&var_offset, ctx->varinfo, ctx->var_index, sizeof(spss_varinfo_t *),
540	                &spss_varinfo_compare);
541	        if (var) {
542	            (*var)->labels_index = ctx->value_labels_count;
543	            value_type = (*var)->type;
544	        }
545	    }
546	
547	    for (i=0; i<label_count; i++) {
548	        value_label_t *vlabel = &value_labels[i];
549	        double val_d = 0.0;
550	        vlabel->final_value.type = value_type;
551	        if (value_type == READSTAT_TYPE_DOUBLE) {
552	            memcpy(&val_d, vlabel->raw_value, 8);
553	            if (ctx->bswap)
554	                val_d = byteswap_double(val_d);
555	
556	            vlabel->final_value.v.double_value = val_d;
557	            sav_tag_missing_double(&vlabel->final_value, ctx);
558	        } else {
559	            retval = readstat_convert(vlabel->utf8_string_value, sizeof(vlabel->utf8_string_value),
560	                    vlabel->raw_value, 8, ctx->converter);
561	            if (retval != READSTAT_OK)
562	                break;
563	
564	            vlabel->final_value.v.string_value = vlabel->utf8_string_value;
565	        }
566	    }
567	
568	    if (ctx->handle.value_label) {
569	        sav_submit_value_labels(value_labels, label_count, value_type, ctx);
570	    }
571	    ctx->value_labels_count++;
572	cleanup:
573	    if (vars)
574	        free(vars);
575	    if (value_labels) {
576	        for (i=0; i<label_count; i++) {
577	            value_label_t *vlabel = &value_labels[i];
578	            if (vlabel->label)
579	                free(vlabel->label);
580	        }
581	        free(value_labels);
582	    }
583	    
584	    return retval;
585	}
