654	static readstat_error_t sav_process_row(unsigned char *buffer, size_t buffer_len, sav_ctx_t *ctx) {
655	    readstat_error_t retval = READSTAT_OK;
656	    double fp_value;
657	    int offset = 0;
658	    readstat_off_t data_offset = 0;
659	    size_t raw_str_used = 0;
660	    int segment_offset = 0;
661	    int var_index = 0, col = 0;
662	
663	    while (data_offset < buffer_len && col < ctx->var_index) {
664	        spss_varinfo_t *col_info = ctx->varinfo[col];
665	        spss_varinfo_t *var_info = ctx->varinfo[var_index];
666	        readstat_value_t value = { .type = var_info->type };
667	        if (offset > 31) {
668	            retval = READSTAT_ERROR_PARSE;
669	            goto done;
670	        }
671	        if (var_info->type == READSTAT_TYPE_STRING) {
672	            if (raw_str_used + 8 <= ctx->raw_string_len) {
673	                memcpy(ctx->raw_string + raw_str_used, &buffer[data_offset], 8);
674	                raw_str_used += 8;
675	            }
676	            if (++offset == col_info->width) {
677	                if (++segment_offset < var_info->n_segments) {
678	                    raw_str_used--;
679	                }
680	                offset = 0;
681	                col++;
682	            }
683	            if (segment_offset == var_info->n_segments) {
684	                if (!ctx->variables[var_info->index]->skip) {
685	                    retval = readstat_convert(ctx->utf8_string, ctx->utf8_string_len, 
686	                            ctx->raw_string, raw_str_used, ctx->converter);
687	                    if (retval != READSTAT_OK)
688	                        goto done;
689	                    value.v.string_value = ctx->utf8_string;
690	                    if (ctx->handle.value(ctx->current_row, ctx->variables[var_info->index],
691	                                value, ctx->user_ctx) != READSTAT_HANDLER_OK) {
692	                        retval = READSTAT_ERROR_USER_ABORT;
693	                        goto done;
694	                    }
695	                }
696	                raw_str_used = 0;
697	                segment_offset = 0;
698	                var_index += var_info->n_segments;
699	            }
700	        } else if (var_info->type == READSTAT_TYPE_DOUBLE) {
701	            if (!ctx->variables[var_info->index]->skip) {
702	                memcpy(&fp_value, &buffer[data_offset], 8);
703	                if (ctx->bswap) {
704	                    fp_value = byteswap_double(fp_value);
705	                }
706	                value.v.double_value = fp_value;
707	                sav_tag_missing_double(&value, ctx);
708	                if (ctx->handle.value(ctx->current_row, ctx->variables[var_info->index],
709	                            value, ctx->user_ctx) != READSTAT_HANDLER_OK) {
710	                    retval = READSTAT_ERROR_USER_ABORT;
711	                    goto done;
712	                }
713	            }
714	            var_index += var_info->n_segments;
715	            col++;
716	        }
717	        data_offset += 8;
718	    }
719	    ctx->current_row++;
720	done:
721	    return retval;
722	}
