724	static readstat_error_t sav_read_data(sav_ctx_t *ctx) {
725	    readstat_error_t retval = READSTAT_OK;
726	    size_t longest_string = 256;
727	    int i;
728	
729	    for (i=0; i<ctx->var_index;) {
730	        spss_varinfo_t *info = ctx->varinfo[i];
731	        if (info->string_length > longest_string) {
732	            longest_string = info->string_length;
733	        }
734	        i += info->n_segments;
735	    }
736	
737	    ctx->raw_string_len = longest_string + sizeof(SAV_EIGHT_SPACES)-2;
738	    ctx->raw_string = readstat_malloc(ctx->raw_string_len);
739	
740	    ctx->utf8_string_len = 4*longest_string+1 + sizeof(SAV_EIGHT_SPACES)-2;
741	    ctx->utf8_string = readstat_malloc(ctx->utf8_string_len);
742	
743	    if (ctx->raw_string == NULL || ctx->utf8_string == NULL) {
744	        retval = READSTAT_ERROR_MALLOC;
745	        goto done;
746	    }
747	
748	    if (ctx->compression == READSTAT_COMPRESS_ROWS) {
749	        retval = sav_read_compressed_data(ctx, &sav_process_row);
750	    } else if (ctx->compression == READSTAT_COMPRESS_BINARY) {
751	#if HAVE_ZLIB
752	        retval = zsav_read_compressed_data(ctx, &sav_process_row);
753	#else
754	        retval = READSTAT_ERROR_UNSUPPORTED_COMPRESSION;
755	#endif
756	    } else {
757	        retval = sav_read_uncompressed_data(ctx, &sav_process_row);
758	    }
759	    if (retval != READSTAT_OK)
760	        goto done;
761	
762	    if (ctx->record_count != -1 && ctx->current_row != ctx->row_limit) {
763	        retval = READSTAT_ERROR_ROW_COUNT_MISMATCH;
764	    }
765	
766	done:
767	    return retval;
768	}
