770	static readstat_error_t sav_read_uncompressed_data(sav_ctx_t *ctx,
771	        readstat_error_t (*row_handler)(unsigned char *, size_t, sav_ctx_t *)) {
772	    readstat_error_t retval = READSTAT_OK;
773	    readstat_io_t *io = ctx->io;
774	    unsigned char *buffer = NULL;
775	    size_t bytes_read = 0;
776	    size_t buffer_len = ctx->var_offset * 8;
777	
778	    buffer = readstat_malloc(buffer_len);
779	
780	    while (ctx->row_limit == -1 || ctx->current_row < ctx->row_limit) {
781	        retval = sav_update_progress(ctx);
782	        if (retval != READSTAT_OK)
783	            goto done;
784	
785	        if ((bytes_read = io->read(buffer, buffer_len, io->io_ctx)) != buffer_len)
786	            goto done;
787	
788	        retval = row_handler(buffer, buffer_len, ctx);
789	        if (retval != READSTAT_OK)
790	            goto done;
791	    }
792	done:
793	    if (buffer)
794	        free(buffer);
795	
796	    return retval;
797	}
798	
799	static readstat_error_t sav_read_compressed_data(sav_ctx_t *ctx,
800	        readstat_error_t (*row_handler)(unsigned char *, size_t, sav_ctx_t *)) {
801	    readstat_error_t retval = READSTAT_OK;
802	    readstat_io_t *io = ctx->io;
803	    readstat_off_t data_offset = 0;
804	    unsigned char buffer[DATA_BUFFER_SIZE];
805	    int buffer_used = 0;
806	
807	    size_t uncompressed_row_len = ctx->var_offset * 8;
808	    readstat_off_t uncompressed_offset = 0;
809	    unsigned char *uncompressed_row = NULL;
810	
811	    struct sav_row_stream_s state = { 
812	        .missing_value = ctx->missing_double,
813	        .bias = ctx->bias,
814	        .bswap = ctx->bswap };
815	
816	    if (uncompressed_row_len && (uncompressed_row = readstat_malloc(uncompressed_row_len)) == NULL) {
817	        retval = READSTAT_ERROR_MALLOC;
818	        goto done;
819	    }
820	
821	    while (1) {
822	        buffer_used = io->read(buffer, sizeof(buffer), io->io_ctx);
823	        if (buffer_used == -1 || buffer_used == 0 || (buffer_used % 8) != 0)
824	            goto done;
825	
826	        state.status = SAV_ROW_STREAM_HAVE_DATA;
827	        data_offset = 0;
828	
829	        while (state.status != SAV_ROW_STREAM_NEED_DATA) {
830	            state.next_in = &buffer[data_offset];
831	            state.avail_in = buffer_used - data_offset;
832	
833	            state.next_out = &uncompressed_row[uncompressed_offset];
834	            state.avail_out = uncompressed_row_len - uncompressed_offset;
835	
836	            sav_decompress_row(&state);
837	
838	            uncompressed_offset = uncompressed_row_len - state.avail_out;
839	            data_offset = buffer_used - state.avail_in;
840	
841	            if (state.status == SAV_ROW_STREAM_FINISHED_ROW) {
842	                retval = row_handler(uncompressed_row, uncompressed_row_len, ctx);
843	                if (retval != READSTAT_OK)
844	                    goto done;
845	
846	                uncompressed_offset = 0;
847	            }
848	
849	            if (state.status == SAV_ROW_STREAM_FINISHED_ALL || ctx->current_row == ctx->row_limit)
850	                goto done;
851	        }
852	    }
853	
854	done:
855	    if (uncompressed_row)
856	        free(uncompressed_row);
857	
858	    return retval;
859	}
