861	static readstat_error_t sav_parse_machine_integer_info_record(const void *data, size_t data_len, sav_ctx_t *ctx) {
862	    if (data_len != 32)
863	        return READSTAT_ERROR_PARSE;
864	
865	    const char *src_charset = NULL;
866	    const char *dst_charset = ctx->output_encoding;
867	    sav_machine_integer_info_record_t record;
868	    memcpy(&record, data, data_len);
869	    if (ctx->bswap) {
870	        record.character_code = byteswap4(record.character_code);
871	    }
872	    if (ctx->input_encoding) {
873	        src_charset = ctx->input_encoding;
874	    } else {
875	        int i;
876	        for (i=0; i<sizeof(_charset_table)/sizeof(_charset_table[0]); i++) {
877	            if (record.character_code  == _charset_table[i].code) {
878	                src_charset = _charset_table[i].name;
879	                break;
880	            }
881	        }
882	        if (src_charset == NULL) {
883	            if (ctx->handle.error) {
884	                char error_buf[1024];
885	                snprintf(error_buf, sizeof(error_buf), "Unsupported character set: %d\n", record.character_code);
886	                ctx->handle.error(error_buf, ctx->user_ctx);
887	            }
888	            return READSTAT_ERROR_UNSUPPORTED_CHARSET;
889	        }
890	        ctx->input_encoding = src_charset;
891	    }
892	    if (src_charset && dst_charset && strcmp(src_charset, dst_charset) != 0) {
893	        iconv_t converter = iconv_open(dst_charset, src_charset);
894	        if (converter == (iconv_t)-1) {
895	            return READSTAT_ERROR_UNSUPPORTED_CHARSET;
896	        }
897	        if (ctx->converter) {
898	            iconv_close(ctx->converter);
899	        }
900	        ctx->converter = converter;
901	    }
902	    return READSTAT_OK;
903	}
