963	static readstat_error_t sav_parse_long_value_labels_record(const void *data, size_t size, size_t count, sav_ctx_t *ctx) {
964	    if (!ctx->handle.value_label)
965	        return READSTAT_OK;
966	    if (size != 1)
967	        return READSTAT_ERROR_PARSE;
968	
969	    readstat_error_t retval = READSTAT_OK;
970	    uint32_t label_name_len = 0;
971	    uint32_t label_count = 0;
972	    uint32_t i = 0;
973	    const char *data_ptr = data;
974	    const char *data_end = data_ptr + count;
975	    char var_name_buf[256*4+1];
976	    char label_name_buf[256];
977	    char *value_buffer = NULL;
978	    char *label_buffer = NULL;
979	    
980	    memset(label_name_buf, '\0', sizeof(label_name_buf));
981	
982	    if (data_ptr + sizeof(uint32_t) > data_end) {
983	        retval = READSTAT_ERROR_PARSE;
984	        goto cleanup;
985	    }
986	
987	    memcpy(&label_name_len, data_ptr, sizeof(uint32_t));
988	    if (ctx->bswap)
989	        label_name_len = byteswap4(label_name_len);
990	
991	    data_ptr += sizeof(uint32_t);
992	
993	    if (data_ptr + label_name_len > data_end) {
994	        retval = READSTAT_ERROR_PARSE;
995	        goto cleanup;
996	    }
997	
998	    retval = readstat_convert(var_name_buf, sizeof(var_name_buf), data_ptr, label_name_len, ctx->converter);
999	    if (retval != READSTAT_OK)
1000	        goto cleanup;
1001	
1002	    data_ptr += label_name_len;
1003	
1004	    for (i=0; i<ctx->var_index;) {
1005	        spss_varinfo_t *info = ctx->varinfo[i];
1006	        if (strcmp(var_name_buf, info->longname) == 0) {
1007	            info->labels_index = ctx->value_labels_count++;
1008	            snprintf(label_name_buf, sizeof(label_name_buf),
1009	                     SAV_LABEL_NAME_PREFIX "%d", info->labels_index);
1010	            break;
1011	        }
1012	        i += info->n_segments;
1013	    }
1014	    
1015	    if (label_name_buf[0] == '\0') {
1016	        retval = READSTAT_ERROR_PARSE;
1017	        goto cleanup;
1018	    }
1019	
1020	    data_ptr += sizeof(uint32_t);
1021	
1022	    if (data_ptr + sizeof(uint32_t) > data_end) {
1023	        retval = READSTAT_ERROR_PARSE;
1024	        goto cleanup;
1025	    }
1026	
1027	    memcpy(&label_count, data_ptr, sizeof(uint32_t));
1028	    if (ctx->bswap)
1029	        label_count = byteswap4(label_count);
1030	
1031	    data_ptr += sizeof(uint32_t);
1032	
1033	    for (i=0; i<label_count; i++) {
1034	        uint32_t value_len = 0, label_len = 0;
1035	        uint32_t value_buffer_len = 0, label_buffer_len = 0;
1036	
1037	        if (data_ptr + sizeof(uint32_t) > data_end) {
1038	            retval = READSTAT_ERROR_PARSE;
1039	            goto cleanup;
1040	        }
1041	
1042	        memcpy(&value_len, data_ptr, sizeof(uint32_t));
1043	        if (ctx->bswap)
1044	            value_len = byteswap4(value_len);
1045	
1046	        data_ptr += sizeof(uint32_t);
1047	
1048	        value_buffer_len = value_len*4+1;
1049	        value_buffer = readstat_realloc(value_buffer, value_buffer_len);
1050	        if (value_buffer == NULL) {
1051	            retval = READSTAT_ERROR_MALLOC;
1052	            goto cleanup;
1053	        }
1054	
1055	        if (data_ptr + value_len > data_end) {
1056	            retval = READSTAT_ERROR_PARSE;
1057	            goto cleanup;
1058	        }
1059	
1060	        retval = readstat_convert(value_buffer, value_buffer_len, data_ptr, value_len, ctx->converter);
1061	        if (retval != READSTAT_OK)
1062	            goto cleanup;
1063	
1064	        data_ptr += value_len;
1065	
1066	        if (data_ptr + sizeof(uint32_t) > data_end) {
1067	            retval = READSTAT_ERROR_PARSE;
1068	            goto cleanup;
1069	        }
1070	
1071	        memcpy(&label_len, data_ptr, sizeof(uint32_t));
1072	        if (ctx->bswap)
1073	            label_len = byteswap4(label_len);
1074	
1075	        data_ptr += sizeof(uint32_t);
1076	
1077	        label_buffer_len = label_len*4+1;
1078	        label_buffer = readstat_realloc(label_buffer, label_buffer_len);
1079	        if (label_buffer == NULL) {
1080	            retval = READSTAT_ERROR_MALLOC;
1081	            goto cleanup;
1082	        }
1083	
1084	        if (data_ptr + label_len > data_end) {
1085	            retval = READSTAT_ERROR_PARSE;
1086	            goto cleanup;
1087	        }
1088	
1089	        retval = readstat_convert(label_buffer, label_buffer_len, data_ptr, label_len, ctx->converter);
1090	        if (retval != READSTAT_OK)
1091	            goto cleanup;
1092	
1093	        data_ptr += label_len;
1094	
1095	        readstat_value_t value = { .type = READSTAT_TYPE_STRING };
1096	        value.v.string_value = value_buffer;
1097	
1098	        if (ctx->handle.value_label(label_name_buf, value, label_buffer, ctx->user_ctx) != READSTAT_HANDLER_OK) {
1099	            retval = READSTAT_ERROR_USER_ABORT;
1100	            goto cleanup;
1101	        }
1102	    }
1103	
1104	cleanup:
1105	    if (value_buffer)
1106	        free(value_buffer);
1107	    if (label_buffer)
1108	        free(label_buffer);
1109	    return retval;
1110	}
