1112	static readstat_error_t sav_parse_records_pass1(sav_ctx_t *ctx) {
1113	    char data_buf[4096];
1114	    readstat_error_t retval = READSTAT_OK;
1115	    readstat_io_t *io = ctx->io;
1116	    while (1) {
1117	        uint32_t rec_type;
1118	        uint32_t extra_info[3];
1119	        size_t data_len = 0;
1120	        int i;
1121	        int done = 0;
1122	        if (io->read(&rec_type, sizeof(uint32_t), io->io_ctx) < sizeof(uint32_t)) {
1123	            retval = READSTAT_ERROR_READ;
1124	            goto cleanup;
1125	        }
1126	        
1127	        if (ctx->bswap) {
1128	            rec_type = byteswap4(rec_type);
1129	        }
1130	        
1131	        switch (rec_type) {
1132	            case SAV_RECORD_TYPE_VARIABLE:
1133	                retval = sav_skip_variable_record(ctx);
1134	                if (retval != READSTAT_OK)
1135	                    goto cleanup;
1136	                break;
1137	            case SAV_RECORD_TYPE_VALUE_LABEL:
1138	                retval = sav_skip_value_label_record(ctx);
1139	                if (retval != READSTAT_OK)
1140	                    goto cleanup;
1141	                break;
1142	            case SAV_RECORD_TYPE_DOCUMENT:
1143	                retval = sav_skip_document_record(ctx);
1144	                if (retval != READSTAT_OK)
1145	                    goto cleanup;
1146	                break;
1147	            case SAV_RECORD_TYPE_DICT_TERMINATION:
1148	                done = 1;
1149	                break;
1150	            case SAV_RECORD_TYPE_HAS_DATA:
1151	                if (io->read(extra_info, sizeof(extra_info), io->io_ctx) < sizeof(extra_info)) {
1152	                    retval = READSTAT_ERROR_READ;
1153	                    goto cleanup;
1154	                }
1155	                if (ctx->bswap) {
1156	                    for (i=0; i<3; i++)
1157	                        extra_info[i] = byteswap4(extra_info[i]);
1158	                }
1159	                uint32_t subtype = extra_info[0];
1160	                size_t size = extra_info[1];
1161	                size_t count = extra_info[2];
1162	                data_len = size * count;
1163	                if (subtype == SAV_RECORD_SUBTYPE_INTEGER_INFO) {
1164	                    if (data_len > sizeof(data_buf)) {
1165	                        retval = READSTAT_ERROR_PARSE;
1166	                        goto cleanup;
1167	                    }
1168	                    if (io->read(data_buf, data_len, io->io_ctx) < data_len) {
1169	                        retval = READSTAT_ERROR_PARSE;
1170	                        goto cleanup;
1171	                    }
1172	                    retval = sav_parse_machine_integer_info_record(data_buf, data_len, ctx);
1173	                    if (retval != READSTAT_OK)
1174	                        goto cleanup;
1175	                } else {
1176	                    if (io->seek(data_len, READSTAT_SEEK_CUR, io->io_ctx) == -1) {
1177	                        retval = READSTAT_ERROR_SEEK;
1178	                        goto cleanup;
1179	                    }
1180	                }
1181	                break;
1182	            default:
1183	                retval = READSTAT_ERROR_PARSE;
1184	                goto cleanup;
1185	                break;
1186	        }
1187	        if (done)
1188	            break;
1189	    }
1190	cleanup:
1191	    return retval;
1192	}
