1194	static readstat_error_t sav_parse_records_pass2(sav_ctx_t *ctx) {
1195	    void *data_buf = NULL;
1196	    size_t data_buf_capacity = 4096;
1197	    readstat_error_t retval = READSTAT_OK;
1198	    readstat_io_t *io = ctx->io;
1199	
1200	    if ((data_buf = readstat_malloc(data_buf_capacity)) == NULL) {
1201	        retval = READSTAT_ERROR_MALLOC;
1202	        goto cleanup;
1203	    }
1204	
1205	    while (1) {
1206	        uint32_t rec_type;
1207	        uint32_t extra_info[3];
1208	        size_t data_len = 0;
1209	        int i;
1210	        int done = 0;
1211	        if (io->read(&rec_type, sizeof(uint32_t), io->io_ctx) < sizeof(uint32_t)) {
1212	            retval = READSTAT_ERROR_READ;
1213	            goto cleanup;
1214	        }
1215	        
1216	        if (ctx->bswap) {
1217	            rec_type = byteswap4(rec_type);
1218	        }
1219	        
1220	        switch (rec_type) {
1221	            case SAV_RECORD_TYPE_VARIABLE:
1222	                if ((retval = sav_read_variable_record(ctx)) != READSTAT_OK)
1223	                    goto cleanup;
1224	                break;
1225	            case SAV_RECORD_TYPE_VALUE_LABEL:
1226	                if ((retval = sav_read_value_label_record(ctx)) != READSTAT_OK)
1227	                    goto cleanup;
1228	                break;
1229	            case SAV_RECORD_TYPE_DOCUMENT:
1230	                if ((retval = sav_read_document_record(ctx)) != READSTAT_OK)
1231	                    goto cleanup;
1232	                break;
1233	            case SAV_RECORD_TYPE_DICT_TERMINATION:
1234	                if ((retval = sav_read_dictionary_termination_record(ctx)) != READSTAT_OK)
1235	                    goto cleanup;
1236	                done = 1;
1237	                break;
1238	            case SAV_RECORD_TYPE_HAS_DATA:
1239	                if (io->read(extra_info, sizeof(extra_info), io->io_ctx) < sizeof(extra_info)) {
1240	                    retval = READSTAT_ERROR_READ;
1241	                    goto cleanup;
1242	                }
1243	                if (ctx->bswap) {
1244	                    for (i=0; i<3; i++)
1245	                        extra_info[i] = byteswap4(extra_info[i]);
1246	                }
1247	                uint32_t subtype = extra_info[0];
1248	                size_t size = extra_info[1];
1249	                size_t count = extra_info[2];
1250	                data_len = size * count;
1251	                if (data_buf_capacity < data_len) {
1252	                    if ((data_buf = readstat_realloc(data_buf, data_buf_capacity = data_len)) == NULL) {
1253	                        retval = READSTAT_ERROR_MALLOC;
1254	                        goto cleanup;
1255	                    }
1256	                }
1257	                if (data_len == 0 || io->read(data_buf, data_len, io->io_ctx) < data_len) {
1258	                    retval = READSTAT_ERROR_PARSE;
1259	                    goto cleanup;
1260	                }
1261	                
1262	                switch (subtype) {
1263	                    case SAV_RECORD_SUBTYPE_INTEGER_INFO:
1264	                        /* parsed in pass 1 */
1265	                        break;
1266	                    case SAV_RECORD_SUBTYPE_FP_INFO:
1267	                        retval = sav_parse_machine_floating_point_record(data_buf, size, count, ctx);
1268	                        if (retval != READSTAT_OK)
1269	                            goto cleanup;
1270	                        break;
1271	                    case SAV_RECORD_SUBTYPE_VAR_DISPLAY:
1272	                        retval = sav_store_variable_display_parameter_record(data_buf, size, count, ctx);
1273	                        if (retval != READSTAT_OK)
1274	                            goto cleanup;
1275	                        break;
1276	                    case SAV_RECORD_SUBTYPE_LONG_VAR_NAME:
1277	                        retval = sav_parse_long_variable_names_record(data_buf, count, ctx);
1278	                        if (retval != READSTAT_OK)
1279	                            goto cleanup;
1280	                        break;
1281	                    case SAV_RECORD_SUBTYPE_VERY_LONG_STR:
1282	                        retval = sav_parse_very_long_string_record(data_buf, count, ctx);
1283	                        if (retval != READSTAT_OK)
1284	                            goto cleanup;
1285	                        break;
1286	                    case SAV_RECORD_SUBTYPE_LONG_VALUE_LABELS:
1287	                        retval = sav_parse_long_value_labels_record(data_buf, size, count, ctx);
1288	                        if (retval != READSTAT_OK)
1289	                            goto cleanup;
1290	                    default: /* misc. info */
1291	                        break;
1292	                }
1293	                break;
1294	            default:
1295	                retval = READSTAT_ERROR_PARSE;
1296	                goto cleanup;
1297	                break;
1298	        }
1299	        if (done)
1300	            break;
1301	    }
1302	cleanup:
1303	    if (data_buf)
1304	        free(data_buf);
1305	    return retval;
1306	}
