1308	static void sav_set_n_segments_and_var_count(sav_ctx_t *ctx) {
1309	    int i;
1310	    ctx->var_count = 0;
1311	    for (i=0; i<ctx->var_index;) {
1312	        spss_varinfo_t *info = ctx->varinfo[i];
1313	        if (info->string_length) {
1314	            info->n_segments = (info->string_length + 251) / 252;
1315	        }
1316	        info->index = ctx->var_count++;
1317	        i += info->n_segments;
1318	    }
1319	    ctx->variables = readstat_calloc(ctx->var_count, sizeof(readstat_variable_t *));
1320	}
1321	
1322	static readstat_error_t sav_handle_variables(sav_ctx_t *ctx) {
1323	    int i;
1324	    int index_after_skipping = 0;
1325	    readstat_error_t retval = READSTAT_OK;
1326	
1327	    if (!ctx->handle.variable)
1328	        return retval;
1329	
1330	    for (i=0; i<ctx->var_index;) {
1331	        char label_name_buf[256];
1332	        spss_varinfo_t *info = ctx->varinfo[i];
1333	        ctx->variables[info->index] = spss_init_variable_for_info(info, index_after_skipping);
1334	
1335	        snprintf(label_name_buf, sizeof(label_name_buf), SAV_LABEL_NAME_PREFIX "%d", info->labels_index);
1336	
1337	        int cb_retval = ctx->handle.variable(info->index, ctx->variables[info->index],
1338	                info->labels_index == -1 ? NULL : label_name_buf,
1339	                ctx->user_ctx);
1340	
1341	        if (cb_retval == READSTAT_HANDLER_ABORT) {
1342	            retval = READSTAT_ERROR_USER_ABORT;
1343	            goto cleanup;
1344	        }
1345	
1346	        if (cb_retval == READSTAT_HANDLER_SKIP_VARIABLE) {
1347	            ctx->variables[info->index]->skip = 1;
1348	        } else {
1349	            index_after_skipping++;
1350	        }
1351	
1352	        i += info->n_segments;
1353	    }
1354	cleanup:
1355	    return retval;
1356	}
1357	
1358	static readstat_error_t sav_handle_fweight(sav_ctx_t *ctx) {
1359	    readstat_error_t retval = READSTAT_OK;
1360	    int i;
1361	    if (ctx->handle.fweight && ctx->fweight_index >= 0) {
1362	        for (i=0; i<ctx->var_index;) {
1363	            spss_varinfo_t *info = ctx->varinfo[i];
1364	            if (info->offset == ctx->fweight_index - 1) {
1365	                if (ctx->handle.fweight(ctx->variables[info->index], ctx->user_ctx) != READSTAT_HANDLER_OK) {
1366	                    retval = READSTAT_ERROR_USER_ABORT;
1367	                    goto cleanup;
1368	                }
1369	                break;
1370	            }
1371	            i += info->n_segments;
1372	        }
1373	    }
1374	cleanup:
1375	    return retval;
1376	}
