1378	readstat_error_t sav_parse_timestamp(sav_ctx_t *ctx, sav_file_header_record_t *header) {
1379	    readstat_error_t retval = READSTAT_OK;
1380	    struct tm timestamp = { .tm_isdst = -1 };
1381	
1382	    if ((retval = sav_parse_time(header->creation_time, sizeof(header->creation_time),
1383	                    &timestamp, ctx->handle.error, ctx->user_ctx)) 
1384	            != READSTAT_OK)
1385	        goto cleanup;
1386	
1387	    if ((retval = sav_parse_date(header->creation_date, sizeof(header->creation_date),
1388	                    &timestamp, ctx->handle.error, ctx->user_ctx)) 
1389	            != READSTAT_OK)
1390	        goto cleanup;
1391	
1392	    ctx->timestamp = mktime(&timestamp);
1393	
1394	cleanup:
1395	    return retval;
1396	}
