1398	readstat_error_t readstat_parse_sav(readstat_parser_t *parser, const char *path, void *user_ctx) {
1399	    readstat_error_t retval = READSTAT_OK;
1400	    readstat_io_t *io = parser->io;
1401	    sav_file_header_record_t header;
1402	    sav_ctx_t *ctx = NULL;
1403	    size_t file_size = 0;
1404	    
1405	    if (io->open(path, io->io_ctx) == -1) {
1406	        return READSTAT_ERROR_OPEN;
1407	    }
1408	
1409	    file_size = io->seek(0, READSTAT_SEEK_END, io->io_ctx);
1410	    if (file_size == -1) {
1411	        retval = READSTAT_ERROR_SEEK;
1412	        goto cleanup;
1413	    }
1414	
1415	    if (io->seek(0, READSTAT_SEEK_SET, io->io_ctx) == -1) {
1416	        retval = READSTAT_ERROR_SEEK;
1417	        goto cleanup;
1418	    }
1419	
1420	    if (io->read(&header, sizeof(sav_file_header_record_t), io->io_ctx) < sizeof(sav_file_header_record_t)) {
1421	        retval = READSTAT_ERROR_READ;
1422	        goto cleanup;
1423	    }
1424	
1425	    ctx = sav_ctx_init(&header, io);
1426	    if (ctx == NULL) {
1427	        retval = READSTAT_ERROR_PARSE;
1428	        goto cleanup;
1429	    }
1430	
1431	    ctx->handle = parser->handlers;
1432	    ctx->input_encoding = parser->input_encoding;
1433	    ctx->output_encoding = parser->output_encoding;
1434	    ctx->user_ctx = user_ctx;
1435	    ctx->file_size = file_size;
1436	    if (parser->row_limit > 0 && (parser->row_limit < ctx->record_count || ctx->record_count == -1)) {
1437	        ctx->row_limit = parser->row_limit;
1438	    } else {
1439	        ctx->row_limit = ctx->record_count;
1440	    }
1441	    
1442	    if ((retval = sav_parse_timestamp(ctx, &header)) != READSTAT_OK)
1443	        goto cleanup;
1444	
1445	    if ((retval = sav_parse_records_pass1(ctx)) != READSTAT_OK)
1446	        goto cleanup;
1447	    
1448	    if (io->seek(sizeof(sav_file_header_record_t), READSTAT_SEEK_SET, io->io_ctx) == -1) {
1449	        retval = READSTAT_ERROR_SEEK;
1450	        goto cleanup;
1451	    }
1452	
1453	    if ((retval = sav_update_progress(ctx)) != READSTAT_OK)
1454	        goto cleanup;
1455	
1456	    if ((retval = sav_parse_records_pass2(ctx)) != READSTAT_OK)
1457	        goto cleanup;
1458	 
1459	    sav_set_n_segments_and_var_count(ctx);
1460	
1461	    if (ctx->var_count == 0) {
1462	        retval = READSTAT_ERROR_PARSE;
1463	        goto cleanup;
1464	    }
1465	
1466	    if (ctx->handle.metadata) {
1467	        readstat_metadata_t metadata = {
1468	            .row_count = ctx->record_count == -1 ? -1 : ctx->row_limit,
1469	            .var_count = ctx->var_count,
1470	            .file_encoding = ctx->input_encoding,
1471	            .file_format_version = ctx->format_version,
1472	            .creation_time = ctx->timestamp,
1473	            .modified_time = ctx->timestamp,
1474	            .compression = ctx->compression,
1475	            .endianness = ctx->endianness
1476	        };
1477	        if ((retval = readstat_convert(ctx->file_label, sizeof(ctx->file_label),
1478	                        header.file_label, sizeof(header.file_label), ctx->converter)) != READSTAT_OK)
1479	            goto cleanup;
1480	
1481	        metadata.file_label = ctx->file_label;
1482	
1483	        if (ctx->handle.metadata(&metadata, ctx->user_ctx) != READSTAT_HANDLER_OK) {
1484	            retval = READSTAT_ERROR_USER_ABORT;
1485	            goto cleanup;
1486	        }
1487	    }
1488	
1489	    sav_parse_variable_display_parameter_record(ctx);
1490	
1491	    if ((retval = sav_handle_variables(ctx)) != READSTAT_OK)
1492	        goto cleanup;
1493	
1494	    if ((retval = sav_handle_fweight(ctx)) != READSTAT_OK)
1495	        goto cleanup;
1496	
1497	    if (ctx->handle.value) {
1498	        retval = sav_read_data(ctx);
1499	    }
1500	    
1501	cleanup:
1502	    io->close(io->io_ctx);
1503	    if (ctx)
1504	        sav_ctx_free(ctx);
1505	    
1506	    return retval;
1507	}
