49	int spss_format(char *buffer, size_t len, spss_format_t *format) {
50	    if (format->type < 0 
51	            || format->type >= sizeof(spss_type_strings)/sizeof(spss_type_strings[0])
52	            || spss_type_strings[format->type][0] == '\0') {
53	        return 0;
54	    }
55	    char *string = spss_type_strings[format->type];
56	
57	    if (format->decimal_places || format->type == SPSS_FORMAT_TYPE_F) {
58	        snprintf(buffer, len, "%s%d.%d", string, format->width, format->decimal_places);
59	    } else if (format->width) {
60	        snprintf(buffer, len, "%s%d", string, format->width);
61	    } else {
62	        snprintf(buffer, len, "%s", string);
63	    }
64	
65	    return 1;
66	}
