84	static readstat_value_t spss_boxed_value(double fp_value) {
85	    readstat_value_t value = {
86	        .type = READSTAT_TYPE_DOUBLE,
87	        .v = { .double_value = fp_value },
88	        .is_system_missing = isnan(fp_value)
89	    };
90	    return value;
