93	uint64_t spss_64bit_value(readstat_value_t value) {
94	    double dval = readstat_double_value(value);
95	    uint64_t special_val;
96	    memcpy(&special_val, &dval, sizeof(double));
97	
98	    if (isinf(dval)) {
99	        if (dval < 0.0) {
100	            special_val = SAV_LOWEST_DOUBLE;
101	        } else {
102	            special_val = SAV_HIGHEST_DOUBLE;
103	        }
104	    } else if (isnan(dval)) {
105	        special_val = SAV_MISSING_DOUBLE;
106	    }
107	    return special_val;
108	}
