113	
114	    if (info->missing_range) {
115	        missingness.missing_ranges_count++;
116	        missingness.missing_ranges[0] = spss_boxed_value(info->missing_values[0]);
117	        missingness.missing_ranges[1] = spss_boxed_value(info->missing_values[1]);
118	
119	        if (info->n_missing_values == 3) {
120	            missingness.missing_ranges_count++;
121	            missingness.missing_ranges[2] = missingness.missing_ranges[3] = spss_boxed_value(info->missing_values[2]);
122	        }
123	    } else if (info->n_missing_values > 0) {
124	        missingness.missing_ranges_count = info->n_missing_values;
125	        int i=0;
126	        for (i=0; i<info->n_missing_values; i++) {
127	            missingness.missing_ranges[2*i] = missingness.missing_ranges[2*i+1] = spss_boxed_value(info->missing_values[i]);
128	        }
129	    }
130	    return missingness;
131	}
